"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[44162],{3676:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>h,default:()=>u,frontMatter:()=>r,metadata:()=>s,toc:()=>c});const s=JSON.parse('{"id":"math/redplum","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/math/redplum.md","sourceDirName":"math","slug":"/math/redplum","permalink":"/math/redplum","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"redplum","title":"","hide_table_of_contents":true},"sidebar":"mathSidebar","previous":{"title":"\u8fde\u8f7d3\uff1a\u6570\u5b66\uff0c\u4e16\u754c\u4e4b\u738b\uff1a\u95f2\u8c08\u73b0\u4ee3\u6570\u5b66\u7684\u57fa\u7840\u95ee\u9898\uff01 (2006/3/6 17:49:05)","permalink":"/math/basics3"},"next":{"title":"\u7b2c\u4e00\u6b21\uff0c\u4e2d\u56fd\u79d1\u5b66\u53d6\u5f97\u5212\u65f6\u4ee3\u7684\u6210\u5c31\uff01 (2006/6/4 19:23:04)","permalink":"/math/landmarkachievement"}}');var i=a(74848),n=a(28453),o=a(17348);const r={id:"redplum",title:"",hide_table_of_contents:!0},h=void 0,l={},c=[...o.RM];function m(e){return(0,i.jsx)(o.Ay,{})}function u(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(m,{...e})}):m()}},17348:(e,t,a)=>{a.d(t,{Ay:()=>r,RM:()=>n});var s=a(74848),i=a(28453);const n=[];function o(e){const t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"if-its-a-red-apricot-it-must-climb-over-the-wallan-apricot-that-doesnt-is-imperfect",children:"If It's a Red Apricot, It Must Climb Over the Wall\u2014An Apricot That Doesn't Is Imperfect!"})}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"2006/4/5 17:00:52"}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:'What is mathematics? Mathematics is beauty, mathematics is music, mathematics is the expanse of azure sky one beholds when one "walks to where the water ends and sits watching the clouds rise." Those who take numbers, axioms, sets, and roots of equations to be mathematics are boors who want the box but not the pearl\u2014how are they fit to discuss mathematics? Those who treat mathematics merely as a tool are like those foul ape-men who treat women merely as tools\u2014with their crude taste, how could they distinguish a wildflower from a peony? Mathematics is the Queen of the Sciences; all sciences bow before her scepter:'}),"\n",(0,s.jsxs)(t.p,{children:["A: So, is mathematics philosophy, or Being, or something like that?",(0,s.jsx)("br",{}),"\nB: Philosophy is nothing but the helpless groaning of decrepit old men reminiscing about their youth. Being is merely a series of ornate dreams conjured by beings gazing into the empty mirror of non-being. Mathematics is the philosophy of philosophy, the Being of Being, the everything of everything. Mathematics is ineffable.",(0,s.jsx)("br",{}),"\nA: So, is mathematics the Dao of that old man who rode off on a green ox? The carefree wandering of that petty official of the lacquer garden who couldn't tell himself apart from a butterfly? Or\u2014?",(0,s.jsx)("br",{}),"\nB: How can you equate mathematics with these trivial things! Mathematics is ineffable, mathematics speaks in all things, mathematics is neither mind nor matter, mathematics is both mind and matter, mathematics\u2014",(0,s.jsx)("br",{}),"\nA: Alright, alright, stop talking. I'm dizzy. I'm most afraid of chattering women, even the celestial kind.",(0,s.jsx)("br",{}),"\nB: Beauty is not always beautiful because of beauty. Mathematics speaks in all things, so let this woman use the example of mathematics to demonstrate to all beings in the universe such as Mr. A that an apricot that doesn't climb over the wall is impossible\u2014so that all thieving courage can find no thieving heart, and all thieving hearts can find no thieving courage.",(0,s.jsx)("br",{}),"\nA: \u2014\u2014",(0,s.jsx)("br",{}),"\nB: If the red apricot represents perfection and the wall represents completeness, then any apricot that is truly an apricot must climb over the wall; an apricot that stays inside is impossible. In mathematics, this idea is called Godel's Incompleteness Theorem. If a red apricot is simply a red apricot and a wall is simply a wall, then an equivalent statement is: an apricot inside the wall is always imperfect; to make the apricot perfect, you must let her climb over the wall. The perfection of the red apricot lies in her climbing over the wall.",(0,s.jsx)("br",{}),"\nA: Ah, mathematics can actually be this accessible\u2014she rips open the scars of every man in the universe, filling the cosmos with men's wails.",(0,s.jsx)("br",{}),"\nB: All women will fall in love with mathematics because of Godel's theorem.",(0,s.jsx)("br",{}),"\nA: All men will despise mathematics because of Godel's theorem.",(0,s.jsx)("br",{}),"\nB: Mathematics pays no heed to love and hate and such trifles, because she is love and hate; mathematics has no fantasies, because she is fantasy; mathematics has no truth, because she is truth. Mathematics\u2014it is not mathematics, which is why it is called mathematics.",(0,s.jsx)("br",{}),"\nA: Alright, alright, stop. Mathematics is about to become a woman's toy. I'm out\u2014is that acceptable?"]}),"\n",(0,s.jsx)(t.p,{children:"The above dialogue is entirely fictional. Any resemblance is purely coincidental."})]})}function r(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(o,{...e})}):o(e)}},28453:(e,t,a)=>{a.d(t,{R:()=>o,x:()=>r});var s=a(96540);const i={},n=s.createContext(i);function o(e){const t=s.useContext(n);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),s.createElement(n.Provider,{value:t},e.children)}}}]);